// Unit tests for the Qwen3.5 GatedDeltaNet stateful primitives in nnml/ssm.h:
//   - nnml_ssm_conv1d_update        : depthwise causal Conv1d recurrent update
//   - nnml_ssm_gated_delta_rule_update : gated delta-rule recurrent update
//   - nnml_ssm_rms_norm_gated       : gated RMSNorm (linear-attn output norm)
//   - nnml_qwen35_partial_rotary    : partial-rotary mRoPE (full-attn layers)
//
// The expected output and expected new conv_state were generated by an
// independent numpy reference (transformers/models/qwen3_5/modeling_qwen3_5.py
// torch_causal_conv1d_update, collapsed to the decode / single-token case):
//
//   import numpy as np
//   def silu(v): return v / (1.0 + np.exp(-v))
//   rng = np.random.RandomState(20240728)
//   x     = (rng.randn(conv_dim)       * 0.7).astype(np.float32)
//   state = (rng.randn(conv_dim,kernel) * 0.5).astype(np.float32)   # last kernel inputs
//   w     = (rng.randn(conv_dim,kernel) * 0.3).astype(np.float32)
//   state2 = state.copy()
//   state2[:, :-1] = state[:, 1:]   # shift left (drop oldest, idx 0)
//   state2[:, -1]  = x              # append new at the end
//   out = silu((state2 * w).sum(axis=1)).astype(np.float32)
//
// This validates both the output AND the in-place conv_state mutation against HF.

#include <cmath>
#include <cstdio>
#include <cstring>

#include "ssm.h"
#include "tensor.h"
#include "memory.h"

// Forward-declare the scheduler's per-node dispatch entry (defined in
// nnml/src/scheduler.cpp, linked from the nnml lib). We deliberately do NOT
// include "scheduler.h" here: that header *defines* the globals `threadpool`,
// `single_graph`, `multi_graphs`, which would multi-define against the nnml
// shared library. Calling nnml_compute_node directly proves the new ops are
// reachable through the real scheduler dispatch switch (the enum case routes
// NNML_OP_SSM_CONV_UPDATE / NNML_OP_SSM_DELTA_UPDATE to the compute fns), while
// keeping the test free of the full threadpool/scheduler harness.
void nnml_compute_node(nnml_tensor * node, const nnml_compute_state * params);

static int g_fails = 0;

static const int g_conv_dim = 8;
static const int g_kernel = 4;

