static void check_main_update(void) {
    float state[8 * 4];
    float out[8];
    std::memcpy(state, g_state_in, sizeof(state));

    nnml_ssm_conv1d_update(g_x_in, state, g_w_in, g_conv_dim, g_kernel, out);

    // Output must match the numpy reference within f32 precision.
    for (int c = 0; c < g_conv_dim; ++c) {
        float got = out[c];
        float expv = g_out_expected[c];
        if (std::fabs(got - expv) > 1e-5f) {
            printf("FAIL out[%d]: got %.9f, expected %.9f\n", c, got, expv);
            ++g_fails;
        }
    }
    // conv_state must be mutated in place to the rolled state.
    for (int i = 0; i < g_conv_dim * g_kernel; ++i) {
        float got = state[i];
        float expv = g_state_expected[i];
        if (std::fabs(got - expv) > 1e-5f) {
            printf("FAIL conv_state[%d]: got %.9f, expected %.9f\n", i, got, expv);
            ++g_fails;
        }
    }
}

// Two consecutive updates: after update #1 the rolled state must feed update #2.
// This catches an off-by-one in the roll direction or writing x to the wrong tap.
static void check_two_steps(void) {
    // Independent numpy reference for two steps with the same weights.
    //   step1: state_a = roll(state0) + x0 ; out0 = silu((state_a * w).sum)
    //   step2: state_b = roll(state_a) + x1; out1 = silu((state_b * w).sum)
    // Hard-coded x1 + the resulting state_b / out1 below were produced by the
    // same numpy script (seed kept, second draw for x1).
    const float x1[8] = {
        0.5728960037231445f, 0.7658089995384216f, -1.228420615196228f, -0.8366431593894958f,
        -0.21271979808807373f, -0.0516231469810009f, 1.0186495780944824f, 0.6452329158782959f,
    };
    // Expected state after step 2 (numpy state_b, channel-major: (k,c) at c*kernel+k).
    const float state_b_expected[8 * 4] = {
        0.885799527f, 0.571287036f, -0.731974542f, 0.572896004f, 0.449657410f, 0.182596818f, -0.785962403f, 0.765809000f,
        0.729027450f, 0.506041169f, 0.568452001f, -1.228420615f, -0.090203181f, -0.272124112f, 1.372986913f, -0.836643159f,
        1.052329659f, 0.109724000f, -0.094989255f, -0.212719798f, -0.141164109f, -0.158164412f, -0.455060810f, -0.051623147f,
        0.198634371f, -0.742488980f, 0.293488562f, 1.018649578f, 1.192807198f, -0.185929254f, 0.259672523f, 0.645232916f,
    };
    // Expected out1 (numpy silu((state_b * w).sum(axis=1))).
    const float out1_expected[8] = {
        -0.050489295f, -0.035498492f, 0.583587646f, -0.237792537f, 0.342081100f, -0.090680420f, -0.046983868f, -0.001504717f,
    };

    float state[8 * 4];
    float out[8];
    std::memcpy(state, g_state_in, sizeof(state));

    nnml_ssm_conv1d_update(g_x_in, state, g_w_in, g_conv_dim, g_kernel, out);  // step 1 (discard out)
    nnml_ssm_conv1d_update(x1,        state, g_w_in, g_conv_dim, g_kernel, out);  // step 2

    for (int c = 0; c < g_conv_dim; ++c) {
        if (std::fabs(out[c] - out1_expected[c]) > 1e-5f) {
            printf("FAIL two-step out[%d]: got %.9f, expected %.9f\n", c, out[c], out1_expected[c]);
            ++g_fails;
        }
    }
    for (int i = 0; i < g_conv_dim * g_kernel; ++i) {
        if (std::fabs(state[i] - state_b_expected[i]) > 1e-5f) {
            printf("FAIL two-step state[%d]: got %.9f, expected %.9f\n", i, state[i], state_b_expected[i]);
            ++g_fails;
        }
    }
}

// Degenerate args must be a safe no-op (no crash, no write).
static void check_null_and_degenerate(void) {
    float state[4] = {1, 2, 3, 4};
    float out[4] = {9, 9, 9, 9};
    // null x -> no-op
    nnml_ssm_conv1d_update(nullptr, state, g_w_in, 4, 4, out);
    if (out[0] != 9.0f) { printf("FAIL null x wrote out\n"); ++g_fails; }
    // conv_dim 0 -> no-op
    nnml_ssm_conv1d_update(g_x_in, state, g_w_in, 0, 4, out);
    if (out[0] != 9.0f) { printf("FAIL conv_dim=0 wrote out\n"); ++g_fails; }
    // kernel 0 -> no-op (no taps; output undefined, must not touch it)
    nnml_ssm_conv1d_update(g_x_in, state, g_w_in, 4, 0, out);
    if (out[0] != 9.0f) { printf("FAIL kernel=0 wrote out\n"); ++g_fails; }
}

// ===========================================================================
// nnml_ssm_gated_delta_rule_update — gated delta-rule recurrent update for
// ONE head, ONE token (Qwen3.5 GatedDeltaNet linear attention).
//
// The expected output and expected new recurrent state were generated by an
// independent numpy reference (transformers/models/qwen3_5/modeling_qwen3_5.py
// torch_recurrent_gated_delta_rule, modeling_qwen3_5.py:404-443), collapsed to
// the per-head / single-token decode case and computed in float64:
//
//   def l2norm(x, eps=1e-6): return x / np.sqrt((x*x).sum() + eps)   # HF form
//   def step(q,k,v,g,beta,S,k_dim):
//       qn = l2norm(q) * (1/np.sqrt(k_dim)); kn = l2norm(k)
//       S  = S * np.exp(g)
//       kv_mem = S.T @ kn                 # [v_dim] = sum_k S[k,v]*kn[k]
//       delta  = (v - kv_mem) * beta
//       S  = S + np.outer(kn, delta)      # rank-1 update
//       out = S.T @ qn                    # [v_dim] = sum_k S[k,v]*qn[k]
//       return out, S
//
// Validates output AND the in-place recurrent-state mutation against HF, for
// both a single token and a 2-token sequence (state persistence).
// ===========================================================================

static const int g_kv_dim = 8;   // k_dim == v_dim for this test (math is dim-agnostic)

// Per-token scalars (numpy RandomState 20240728): g is raw (op applies exp(g)).
