// f32 vs float64-reference tolerance: exp + contractions over the recurrent
// state accumulate a few ulps; 1e-4 is comfortable headroom (observed max ~1e-5).
static const float g_delta_tol = 1e-4f;

static void check_delta_rule_one_token(void) {
    float S[64];
    float out[8];
    std::memcpy(S, g_S0_in, sizeof(S));

    nnml_ssm_gated_delta_rule_update(g_q0_in, g_k0_in, g_v0_in,
                                     g_g0, g_beta0, S, g_kv_dim, g_kv_dim, out);

    for (int vv = 0; vv < g_kv_dim; ++vv) {
        if (std::fabs(out[vv] - g_out0_expected[vv]) > g_delta_tol) {
            printf("FAIL delta out0[%d]: got %.9f, expected %.9f\n",
                   vv, out[vv], g_out0_expected[vv]);
            ++g_fails;
        }
    }
    for (int i = 0; i < g_kv_dim * g_kv_dim; ++i) {
        if (std::fabs(S[i] - g_S1_expected[i]) > g_delta_tol) {
            printf("FAIL delta S1[%d]: got %.9f, expected %.9f\n",
                   i, S[i], g_S1_expected[i]);
            ++g_fails;
        }
    }
}

// Two consecutive updates: token 1 mutates S0 -> S1, token 2 mutates S1 -> S2.
// out1 and S2 are checked — this catches state-persistence bugs (e.g. reading
// pre-decay or pre-update S, or wrong contraction axes that only cancel on one
// step).
static void check_delta_rule_two_token(void) {
    float S[64];
    float out[8];
    std::memcpy(S, g_S0_in, sizeof(S));

    nnml_ssm_gated_delta_rule_update(g_q0_in, g_k0_in, g_v0_in,
                                     g_g0, g_beta0, S, g_kv_dim, g_kv_dim, out);  // step 1
    nnml_ssm_gated_delta_rule_update(g_q1_in, g_k1_in, g_v1_in,
                                     g_g1, g_beta1, S, g_kv_dim, g_kv_dim, out);  // step 2

    for (int vv = 0; vv < g_kv_dim; ++vv) {
        if (std::fabs(out[vv] - g_out1_expected[vv]) > g_delta_tol) {
            printf("FAIL delta out1[%d]: got %.9f, expected %.9f\n",
                   vv, out[vv], g_out1_expected[vv]);
            ++g_fails;
        }
    }
    for (int i = 0; i < g_kv_dim * g_kv_dim; ++i) {
        if (std::fabs(S[i] - g_S2_expected[i]) > g_delta_tol) {
            printf("FAIL delta S2[%d]: got %.9f, expected %.9f\n",
                   i, S[i], g_S2_expected[i]);
            ++g_fails;
        }
    }
}

// Degenerate args must be a safe no-op for the delta rule too (no crash/write).
static void check_delta_rule_null_and_degenerate(void) {
    float S[4] = {1, 2, 3, 4};
    float out[4] = {9, 9, 9, 9};
    nnml_ssm_gated_delta_rule_update(nullptr, g_k0_in, g_v0_in, 0.0f, 0.5f, S, 4, 4, out);
    if (out[0] != 9.0f) { printf("FAIL delta null q wrote out\n"); ++g_fails; }
    nnml_ssm_gated_delta_rule_update(g_q0_in, g_k0_in, g_v0_in, 0.0f, 0.5f, nullptr, 4, 4, out);
    if (out[0] != 9.0f) { printf("FAIL delta null S wrote out\n"); ++g_fails; }
    nnml_ssm_gated_delta_rule_update(g_q0_in, g_k0_in, g_v0_in, 0.0f, 0.5f, S, 0, 4, out);
    if (out[0] != 9.0f) { printf("FAIL delta k_dim=0 wrote out\n"); ++g_fails; }
    nnml_ssm_gated_delta_rule_update(g_q0_in, g_k0_in, g_v0_in, 0.0f, 0.5f, S, 4, 0, out);
    if (out[0] != 9.0f) { printf("FAIL delta v_dim=0 wrote out\n"); ++g_fails; }
}

// ===========================================================================
// nnml_ssm_rms_norm_gated — gated RMSNorm for Qwen3.5 GatedDeltaNet output.
//
// Expected output generated by an independent numpy reference matching HF's
// Qwen3_5RMSNormGated.forward (modeling_qwen3_5.py:271-280), computed in
// float64:
//
//   def silu(v): return v / (1.0 + np.exp(-v))
//   var = (x*x).mean()
//   out = weight * (x * (1.0/np.sqrt(var + 1e-6))) * silu(gate)
//
// Inputs use numpy RandomState 20240728 (continuing the same stream as the
// conv1d test). Tolerance 1e-6: only a few ulps of f32 vs float64 drift.
// ===========================================================================

static const int g_norm_n = 8;
static const float g_norm_x[8] = {
    -0.7319745421409607f, -0.7859624028205872f, 0.568452000617981f, 1.372986912727356f,
    -0.09498925507068634f, -0.45506080985069275f, 0.2934885621070862f, 0.25967252254486084f,
};
static const float g_norm_w[8] = {
    1.1589518785476685f, 1.126774787902832f, 1.5314797163009644f, 1.3427722454071045f,
    0.9573260545730591f, 1.051120400428772f, 1.2697944641113281f, 1.10955810546875f,
};
static const float g_norm_gate[8] = {
    -0.49831709265708923f, 0.04675991088151932f, 0.7290274500846863f, 0.5060411691665649f,
    0.06869954615831375f, 0.43477073311805725f, -0.0902031809091568f, -0.27212411165237427f,
};
static const float g_norm_out_expected[8] = {
    0.23393380641937256f, -0.03102594055235386f, 0.6268985867500305f, 0.8522392511367798f,
    -0.0047307200729846954f, -0.18483617901802063f, -0.023501459509134293f, -0.04963884502649307f,
};

static void check_rms_norm_gated(void) {
    float out[8];
    nnml_ssm_rms_norm_gated(g_norm_x, g_norm_w, g_norm_gate, g_norm_n, 1e-6f, out);
    for (int i = 0; i < g_norm_n; ++i) {
        if (std::fabs(out[i] - g_norm_out_expected[i]) > 1e-6f) {
            printf("FAIL rms_norm_gated[%d]: got %.9f, expected %.9f\n",
                   i, out[i], g_norm_out_expected[i]);
            ++g_fails;
        }
    }
}

// In-place aliasing: out == x must work (norm writes from double-buffered
// per-element math, so x is fully consumed before out[i] is written).
static void check_rms_norm_gated_inplace(void) {
    float buf[8];
    std::memcpy(buf, g_norm_x, sizeof(buf));
    nnml_ssm_rms_norm_gated(buf, g_norm_w, g_norm_gate, g_norm_n, 1e-6f, buf);
    for (int i = 0; i < g_norm_n; ++i) {
        if (std::fabs(buf[i] - g_norm_out_expected[i]) > 1e-6f) {
            printf("FAIL rms_norm_gated inplace[%d]: got %.9f, expected %.9f\n",
                   i, buf[i], g_norm_out_expected[i]);
            ++g_fails;
        }
    }
}

static void check_rms_norm_gated_null_and_degenerate(void) {
    float out[4] = {9, 9, 9, 9};
    nnml_ssm_rms_norm_gated(nullptr, g_norm_w, g_norm_gate, 4, 1e-6f, out);
    if (out[0] != 9.0f) { printf("FAIL rms_norm null x wrote out\n"); ++g_fails; }
    nnml_ssm_rms_norm_gated(g_norm_x, g_norm_w, g_norm_gate, 0, 1e-6f, out);
    if (out[0] != 9.0f) { printf("FAIL rms_norm n=0 wrote out\n"); ++g_fails; }
}

// ===========================================================================
// nnml_qwen35_partial_rotary — partial-rotary mRoPE for ONE head, ONE token
// (Qwen3.5 full-attention layers).
//
// Expected output generated two ways and cross-checked:
//   (a) HF apply_rotary_pos_emb (modeling_qwen3_5.py:638-673) with cos/sin
//       built by Qwen3_5TextRotaryEmbedding for a single text position;
//   (b) an independent numpy re-implementation of the documented convention.
//   (a) and (b) agree to 1.2e-7 (f32 precision).
//
// Uses compact dims (head_dim=16, rotary_dim=8) — the rotation math is
// dim-agnostic, and the compact case still exercises: 4 rotated pairs, the
// rotate_half split, and 8 pass-through dims. pos=7, theta=1e7.
//   inv_freq[j] = 1/(theta^(2j/rotary_dim))  j in [0, 4)
//     = [1.0, 0.017782794, 3.1622779e-04, 5.6234135e-06]
// ===========================================================================

static const int  g_pr_head_dim   = 16;
static const int  g_pr_rotary_dim = 8;
static const float g_pr_theta      = 1.0e7f;
static const float g_pr_pos        = 7.0f;
static const float g_pr_q_in[16] = {
    0.16068010032176971f, 0.9715192914009094f, 1.052329659461975f, 0.1097240000963211f,
    0.5461364984512329f, -0.14004598557949066f, -0.14116410911083221f, -0.15816441178321838f,
    0.32755008339881897f, 0.1522490680217743f, 0.19863437116146088f, -0.7424889802932739f,
    -0.06564218550920486f, 0.5532870292663574f, 1.1928071975708008f, -0.18592925369739532f,
};
static const float g_pr_q_out_expected[16] = {
    -0.2376672625541687f, 0.9813899397850037f, 1.0526394844055176f, 0.10973022878170013f,
    0.5172982215881348f, -0.018340155482292175f, -0.13883434236049652f, -0.15816009044647217f,
    0.32755008339881897f, 0.1522490680217743f, 0.19863437116146088f, -0.7424889802932739f,
    -0.06564218550920486f, 0.5532870292663574f, 1.1928071975708008f, -0.18592925369739532f,
};

static void check_partial_rotary(void) {
    float out[16];
    nnml_qwen35_partial_rotary(g_pr_q_in, g_pr_pos, g_pr_head_dim,
                               g_pr_rotary_dim, g_pr_theta, out);
    // Rotated + pass-through must both match HF.
    for (int i = 0; i < g_pr_head_dim; ++i) {
        if (std::fabs(out[i] - g_pr_q_out_expected[i]) > 1e-6f) {
            printf("FAIL partial_rotary[%d]: got %.9f, expected %.9f\n",
                   i, out[i], g_pr_q_out_expected[i]);
            ++g_fails;
        }
    }
}

// In-place aliasing: q_out == q_in must work (the per-pair math reads both
// sources into locals before writing, so an alias is safe).
static void check_partial_rotary_inplace(void) {
    float buf[16];
    std::memcpy(buf, g_pr_q_in, sizeof(buf));
    nnml_qwen35_partial_rotary(buf, g_pr_pos, g_pr_head_dim,
                               g_pr_rotary_dim, g_pr_theta, buf);
    for (int i = 0; i < g_pr_head_dim; ++i) {
        if (std::fabs(buf[i] - g_pr_q_out_expected[i]) > 1e-6f) {
            printf("FAIL partial_rotary inplace[%d]: got %.9f, expected %.9f\n",
                   i, buf[i], g_pr_q_out_expected[i]);
            ++g_fails;
        }
    }
}

// pos=0 is a no-op rotation (cos=1, sin=0) -> output must equal input.
static void check_partial_rotary_zero_pos(void) {
    float out[16];
    nnml_qwen35_partial_rotary(g_pr_q_in, 0.0f, g_pr_head_dim,
                               g_pr_rotary_dim, g_pr_theta, out);
    for (int i = 0; i < g_pr_head_dim; ++i) {
        if (std::fabs(out[i] - g_pr_q_in[i]) > 1e-6f) {
            printf("FAIL partial_rotary pos=0[%d]: got %.9f, expected %.9f\n",
                   i, out[i], g_pr_q_in[i]);
            ++g_fails;
        }
    }
}

// rotary_dim=0 degenerates to a copy (no rotation anywhere).
static void check_partial_rotary_zero_rotary(void) {
    float out[16] = {9,9,9,9,9,9,9,9,9,9,9,9,9,9,9,9};
    nnml_qwen35_partial_rotary(g_pr_q_in, g_pr_pos, g_pr_head_dim, 0, g_pr_theta, out);
    for (int i = 0; i < g_pr_head_dim; ++i) {
        if (std::fabs(out[i] - g_pr_q_in[i]) > 1e-6f) {
            printf("FAIL partial_rotary rotary=0[%d]: got %.9f, expected %.9f\n",
                   i, out[i], g_pr_q_in[i]);
            ++g_fails;
        }
    }
}

static void check_partial_rotary_null_and_degenerate(void) {
    float out[4] = {9, 9, 9, 9};
    nnml_qwen35_partial_rotary(nullptr, g_pr_pos, 4, 4, g_pr_theta, out);
    if (out[0] != 9.0f) { printf("FAIL partial_rotary null q wrote out\n"); ++g_fails; }
    nnml_qwen35_partial_rotary(g_pr_q_in, g_pr_pos, 0, 0, g_pr_theta, out);
    if (out[0] != 9.0f) { printf("FAIL partial_rotary head_dim=0 wrote out\n"); ++g_fails; }
}

// ===========================================================================
// Graph-op integration: prove the side-effecting-op + persistent-state
// mechanism works end-to-end through the scheduler dispatch.
//
// For each new op (nnml_ssm_conv_update, nnml_ssm_delta_update) we build the
// node, run it via nnml_compute_node for "token 0", then re-run the SAME node
// for "token 1" (mirroring how process_ubatch recomputes the graph each token),
// and assert: (a) the node's output matches the standalone primitive for each
// token; (b) the PERSISTENT src tensor (conv_state / recurrent_state, allocated
// as NNML_TENSOR_TYPE_KVCACHE) is mutated correctly across both tokens,
// matching a 2-call standalone reference. This is exactly the property the
// decode path relies on: the graph is rebuilt per ubatch while the KV-resident
// recurrent state survives and is read-modify-written each step.
// ===========================================================================

// A small persistent memory pool: elastic KV buffer (grows on demand) so we do
// not have to size the recurrent state precisely; weight + activation buffers
// are generously pre-sized for the tiny test tensors.
static nnml_memory_t make_graph_test_mem(void) {
    nnml_memory::cparams mp;
    mp.total_wsize_bytes   = (std::size_t) 1 << 20;   // 1 MiB
    mp.total_csize_bytes   = (std::size_t) 1 << 20;
    mp.total_kvsize_bytes  = (std::size_t) 1 << 16;   // 64 KiB (elastic)
    mp.tmp_work_size_bytes = (std::size_t) 1 << 16;
    mp.is_kv_elastic       = true;
    mp.zero_init           = true;
    return nnml_memory::create(mp);
}

// Single-threaded compute state for driving nnml_compute_node directly.
static nnml_compute_state make_compute_state(void) {
    nnml_compute_state st{};
    st.ith = 0;
    st.nth = 1;
    return st;
}

// nnml_ssm_conv_update: 2-token conv-state persistence through the graph.
//
// Reuses the conv1d fixtures (g_x_in / g_state_in / g_w_in / g_out_expected /
// g_state_expected and the two-step x1 / out1_expected / state_b_expected) so
// the graph-op result is checked against the SAME numpy reference as the
// standalone primitive.
static const float g_x1_in[8] = {
    0.5728960037231445f, 0.7658089995384216f, -1.228420615196228f, -0.8366431593894958f,
    -0.21271979808807373f, -0.0516231469810009f, 1.0186495780944824f, 0.6452329158785959f,
};

static void check_graph_conv_update(nnml_memory_t & mem) {
    const int conv_dim = g_conv_dim;   // 8
    const int kernel   = g_kernel;     // 4

    // x: per-token activation. conv_state: PERSISTENT KV tensor ([kernel, conv_dim]).
    // weight: depthwise conv weight (same layout as conv_state).
    nnml_tensor * x      = tensor_new_1d(mem, NNML_TENSOR_TYPE_ACTIVATION, 0, 0, NNML_TYPE_F32, conv_dim);
    nnml_tensor * cstate = tensor_new_2d(mem, NNML_TENSOR_TYPE_KVCACHE,    0, 0, NNML_TYPE_F32, kernel, conv_dim);
    nnml_tensor * weight = tensor_new_2d(mem, NNML_TENSOR_TYPE_WEIGHT,     0, 0, NNML_TYPE_F32, kernel, conv_dim);
    std::memcpy(weight->tensor_data(), g_w_in, sizeof(g_w_in));

    // Initialize the persistent conv_state to the SAME starting state as the
    // standalone reference (so the two are directly comparable).
    std::memcpy(cstate->tensor_data(), g_state_in, sizeof(g_state_in));

    // Build the side-effecting graph node: out = ssm_conv_update(x, cstate, w).
    nnml_tensor * node = nnml_ssm_conv_update(mem, NNML_TENSOR_TYPE_ACTIVATION, 0, 0, x, cstate, weight);

    // Standalone 2-token reference (mutates ref_state in place). After token 0
    // it equals g_state_expected; after token 1 it is the 2-step rolled state.
    float ref_state[8 * 4];
    float ref_out0[8], ref_out1[8];
    std::memcpy(ref_state, g_state_in, sizeof(ref_state));
    nnml_ssm_conv1d_update(g_x_in,  ref_state, g_w_in, conv_dim, kernel, ref_out0);
    nnml_ssm_conv1d_update(g_x1_in, ref_state, g_w_in, conv_dim, kernel, ref_out1);
    // ref_state is now the state after BOTH standalone calls (2-step reference).

    nnml_compute_state st = make_compute_state();

    // --- token 0: feed x0, run the node through the scheduler dispatch. ---
    std::memcpy(x->tensor_data(), g_x_in, sizeof(g_x_in));
    nnml_compute_node(node, &st);
    const float * out0 = (const float *) node->tensor_data();
    const float * cs0  = (const float *) cstate->tensor_data();
    for (int c = 0; c < conv_dim; ++c) {
        if (std::fabs(out0[c] - ref_out0[c]) > 1e-5f) {
            printf("FAIL graph_conv out0[%d]: got %.9f, expected %.9f\n", c, out0[c], ref_out0[c]);
            ++g_fails;
        }
    }
    // Persistent conv_state must have been mutated to the rolled state.
    for (int i = 0; i < conv_dim * kernel; ++i) {
        if (std::fabs(cs0[i] - g_state_expected[i]) > 1e-5f) {
            printf("FAIL graph_conv state0[%d]: got %.9f, expected %.9f\n", i, cs0[i], g_state_expected[i]);
            ++g_fails;
        }
    }

    // --- token 1: re-run the SAME node with new input; state carries over. ---
    std::memcpy(x->tensor_data(), g_x1_in, sizeof(g_x1_in));
    nnml_compute_node(node, &st);
    const float * out1 = (const float *) node->tensor_data();
    const float * cs1  = (const float *) cstate->tensor_data();
    for (int c = 0; c < conv_dim; ++c) {
        if (std::fabs(out1[c] - ref_out1[c]) > 1e-5f) {
            printf("FAIL graph_conv out1[%d]: got %.9f, expected %.9f\n", c, out1[c], ref_out1[c]);
            ++g_fails;
        }
    }
    for (int i = 0; i < conv_dim * kernel; ++i) {
        if (std::fabs(cs1[i] - ref_state[i]) > 1e-5f) {
            printf("FAIL graph_conv state1[%d]: got %.9f, expected %.9f\n", i, cs1[i], ref_state[i]);
            ++g_fails;
        }
    }
}

// nnml_ssm_delta_update: 2-token recurrent-state persistence, looping 2 heads.
//
// head 0 starts from g_S0_in (non-zero); head 1 starts from ZERO state but
// receives the SAME per-token inputs as head 0. Because their initial states
// differ, their outputs differ — so any per-head stride bug (head 1 reading or
// writing head 0's S / out slice) shows up as a mismatch. head 1's reference is
// computed by calling the (already-validated) standalone primitive on a zero
// initial state. Both heads' graph output + mutated recurrent_state are checked
// against their references for token 0 and token 1.
static void check_graph_delta_update(nnml_memory_t & mem) {
    const int k_dim = g_kv_dim;     // 8
    const int v_dim = g_kv_dim;     // 8
    const int num_heads = 2;

    // Per-head-strided inputs: [k_dim, num_heads] for q/k, [v_dim, num_heads] for v.
    nnml_tensor * q    = tensor_new_2d(mem, NNML_TENSOR_TYPE_ACTIVATION, 0, 0, NNML_TYPE_F32, k_dim, num_heads);
    nnml_tensor * k    = tensor_new_2d(mem, NNML_TENSOR_TYPE_ACTIVATION, 0, 0, NNML_TYPE_F32, k_dim, num_heads);
    nnml_tensor * v    = tensor_new_2d(mem, NNML_TENSOR_TYPE_ACTIVATION, 0, 0, NNML_TYPE_F32, v_dim, num_heads);
    nnml_tensor * g    = tensor_new_1d(mem, NNML_TENSOR_TYPE_ACTIVATION, 0, 0, NNML_TYPE_F32, num_heads);
    nnml_tensor * beta = tensor_new_1d(mem, NNML_TENSOR_TYPE_ACTIVATION, 0, 0, NNML_TYPE_F32, num_heads);
    // Persistent recurrent state: [v_dim, k_dim, num_heads] KV tensor.
    nnml_tensor * rstate = tensor_new_3d(mem, NNML_TENSOR_TYPE_KVCACHE, 0, 0, NNML_TYPE_F32, v_dim, k_dim, num_heads);

    // head 0 initial S = g_S0_in; head 1 initial S = zeros.
    float * Sd = (float *) rstate->tensor_data();
    std::memcpy(Sd, g_S0_in, sizeof(g_S0_in));                      // head 0 (offset 0)
    std::memset(Sd + k_dim * v_dim, 0, sizeof(float) * k_dim * v_dim);  // head 1 (offset 64)

    // head 1 standalone reference (continues from the SAME zero initial state).
    float h1_S[64];
    std::memset(h1_S, 0, sizeof(h1_S));
    float h1_out0[8], h1_out1[8];
    // (head 0 reference is the existing g_out0/g_out1/g_S1/g_S2 expected arrays.)

    nnml_tensor * node = nnml_ssm_delta_update(mem, NNML_TENSOR_TYPE_ACTIVATION, 0, 0,
                                               q, k, v, g, beta, rstate);

    nnml_compute_state st = make_compute_state();

    // helper to load per-head inputs (head 1 mirrors head 0's inputs).
    auto load_token_inputs = [&](const float qh0[8], const float kh0[8], const float vh0[8],
                                 float gg, float bb) {
        float * qd = (float *) q->tensor_data();
        float * kd = (float *) k->tensor_data();
        float * vd = (float *) v->tensor_data();
        std::memcpy(qd + 0 * k_dim, qh0, sizeof(float) * k_dim);   // head 0
        std::memcpy(qd + 1 * k_dim, qh0, sizeof(float) * k_dim);   // head 1 = head 0
        std::memcpy(kd + 0 * k_dim, kh0, sizeof(float) * k_dim);
        std::memcpy(kd + 1 * k_dim, kh0, sizeof(float) * k_dim);
        std::memcpy(vd + 0 * v_dim, vh0, sizeof(float) * v_dim);
        std::memcpy(vd + 1 * v_dim, vh0, sizeof(float) * v_dim);
        ((float *) g->tensor_data())[0] = gg;
        ((float *) g->tensor_data())[1] = gg;
        ((float *) beta->tensor_data())[0] = bb;
        ((float *) beta->tensor_data())[1] = bb;
    };

    // --- token 0 ---
    load_token_inputs(g_q0_in, g_k0_in, g_v0_in, g_g0, g_beta0);
    nnml_compute_node(node, &st);
    nnml_ssm_gated_delta_rule_update(g_q0_in, g_k0_in, g_v0_in, g_g0, g_beta0, h1_S, g_kv_dim, g_kv_dim, h1_out0);  // head 1 ref (from zero S)

    const float * out0 = (const float *) node->tensor_data();
    for (int vv = 0; vv < v_dim; ++vv) {
        if (std::fabs(out0[vv] - g_out0_expected[vv]) > g_delta_tol) {
            printf("FAIL graph_delta out0 head0[%d]: got %.9f, expected %.9f\n", vv, out0[vv], g_out0_expected[vv]);
            ++g_fails;
        }
        if (std::fabs(out0[v_dim + vv] - h1_out0[vv]) > g_delta_tol) {
            printf("FAIL graph_delta out0 head1[%d]: got %.9f, expected %.9f\n", vv, out0[v_dim + vv], h1_out0[vv]);
            ++g_fails;
        }
    }
    // recurrent_state after token 0: head 0 == g_S1_expected, head 1 == h1_S.
    for (int i = 0; i < k_dim * v_dim; ++i) {
        if (std::fabs(Sd[i] - g_S1_expected[i]) > g_delta_tol) {
            printf("FAIL graph_delta S0 head0[%d]: got %.9f, expected %.9f\n", i, Sd[i], g_S1_expected[i]);
            ++g_fails;
        }
        if (std::fabs(Sd[k_dim * v_dim + i] - h1_S[i]) > g_delta_tol) {
            printf("FAIL graph_delta S0 head1[%d]: got %.9f, expected %.9f\n", i, Sd[k_dim * v_dim + i], h1_S[i]);
            ++g_fails;
        }
    }

    // --- token 1 ---
    load_token_inputs(g_q1_in, g_k1_in, g_v1_in, g_g1, g_beta1);
    nnml_compute_node(node, &st);
    nnml_ssm_gated_delta_rule_update(g_q1_in, g_k1_in, g_v1_in, g_g1, g_beta1, h1_S, g_kv_dim, g_kv_dim, h1_out1);  // head 1 ref (continued)

    const float * out1 = (const float *) node->tensor_data();
    for (int vv = 0; vv < v_dim; ++vv) {
        if (std::fabs(out1[vv] - g_out1_expected[vv]) > g_delta_tol) {
            printf("FAIL graph_delta out1 head0[%d]: got %.9f, expected %.9f\n", vv, out1[vv], g_out1_expected[vv]);
            ++g_fails;
        }
        if (std::fabs(out1[v_dim + vv] - h1_out1[vv]) > g_delta_tol) {
            printf("FAIL graph_delta out1 head1[%d]: got %.9f, expected %.9f\n", vv, out1[v_dim + vv], h1_out1[vv]);
            ++g_fails;
        }
    }
    for (int i = 0; i < k_dim * v_dim; ++i) {
        if (std::fabs(Sd[i] - g_S2_expected[i]) > g_delta_tol) {
            printf("FAIL graph_delta S1 head0[%d]: got %.9f, expected %.9f\n", i, Sd[i], g_S2_expected[i]);
            ++g_fails;
        }
        if (std::fabs(Sd[k_dim * v_dim + i] - h1_S[i]) > g_delta_tol) {
            printf("FAIL graph_delta S1 head1[%d]: got %.9f, expected %.9f\n", i, Sd[k_dim * v_dim + i], h1_S[i]);
            ++g_fails;
        }
    }
}

static void check_graph_ops(void) {
    nnml_memory_t mem = make_graph_test_mem();
    check_graph_conv_update(mem);
    check_graph_delta_update(mem);
}

// Multi-token conv: process 4 distinct tokens in one seq call; each token's output
// must equal running the (numpy-validated) single-token primitive sequentially with
// the rolling conv_state carried between steps (compositional validation).
static void check_conv_seq(void) {
    const int cd = g_conv_dim, k = g_kernel, T = 4;
    const float xs[4][8] = {
        { -0.731974542f, -0.785962403f,  0.568452001f,  1.372986913f, -0.094989255f, -0.455060810f,  0.293488562f,  0.259672523f },
        {  0.572896004f,  0.765809000f, -1.228420615f, -0.836643159f, -0.212719798f, -0.051623147f,  1.018649578f,  0.645232916f },
        {  0.300000012f, -0.400000006f,  0.899999976f, -0.200000003f,  0.600000024f, -0.699999988f,  0.100000001f,  0.500000000f },
        { -0.800000012f,  0.200000003f, -0.500000000f,  1.100000024f,  0.300000012f, -0.600000024f,  0.400000015f, -0.899999976f },
    };
    float xbuf[4][8];
    for (int t = 0; t < T; ++t)
        for (int c = 0; c < cd; ++c) xbuf[t][c] = xs[t][c];

    // Reference: sequential single-token calls with state carry.
    float state_ref[8 * 4];
    float out_ref[4][8];
    std::memcpy(state_ref, g_state_in, sizeof(state_ref));
    for (int t = 0; t < T; ++t)
        nnml_ssm_conv1d_update(xs[t], state_ref, g_w_in, cd, k, out_ref[t]);

    // Seq wrapper: token-major input, token stride = cd floats.
    float state_seq[8 * 4];
    float out_seq[4][8];
    std::memcpy(state_seq, g_state_in, sizeof(state_seq));
    nnml_ssm_conv1d_update_seq(&xbuf[0][0], cd * sizeof(float), state_seq, g_w_in,
                               cd, k, T, &out_seq[0][0], cd * sizeof(float), 0, 1);

    for (int t = 0; t < T; ++t)
        for (int c = 0; c < cd; ++c)
            if (std::fabs(out_seq[t][c] - out_ref[t][c]) > 1e-5f) {
                printf("FAIL conv_seq out[t=%d,c=%d]: got %.9f, expected %.9f\n", t, c, out_seq[t][c], out_ref[t][c]);
                ++g_fails;
            }
    for (int i = 0; i < cd * k; ++i)
        if (std::fabs(state_seq[i] - state_ref[i]) > 1e-5f) {
            printf("FAIL conv_seq state[%d]: got %.9f, expected %.9f\n", i, state_seq[i], state_ref[i]);
            ++g_fails;
        }
}

// Multi-token + multi-head delta seq: validates the seq wrapper against the
// numpy-validated single-token fixtures. (a) 2 tokens, 1 head == the existing
// two-token reference (g_out1/g_S2_expected). (b) 1 token, 2 heads (head1 an
// independent copy of head0) == the single-token result, exercising the head loop.
static void check_delta_seq(void) {
    const int KD = g_kv_dim, VD = g_kv_dim;   // 8

    // (a) 2 tokens, 1 head: q/k/v [KD,1,2], g/beta [1,2].
    float q2[16], k2[16], v2[16];
    float g2[2] = { g_g0, g_g1 };
    float b2[2] = { g_beta0, g_beta1 };
    std::memcpy(q2, g_q0_in, 8 * sizeof(float)); std::memcpy(q2 + 8, g_q1_in, 8 * sizeof(float));
    std::memcpy(k2, g_k0_in, 8 * sizeof(float)); std::memcpy(k2 + 8, g_k1_in, 8 * sizeof(float));
    std::memcpy(v2, g_v0_in, 8 * sizeof(float)); std::memcpy(v2 + 8, g_v1_in, 8 * sizeof(float));
    float S[64]; std::memcpy(S, g_S0_in, sizeof(S));
    float out[16];
    nnml_ssm_delta_rule_update_seq(q2, KD * sizeof(float), k2, KD * sizeof(float),
                                   v2, VD * sizeof(float), g2, sizeof(float),
                                   b2, sizeof(float), S, KD, VD, 1, 2,
                                   out, VD * sizeof(float), 0, 1);
    for (int vv = 0; vv < VD; ++vv)
        if (std::fabs(out[8 + vv] - g_out1_expected[vv]) > g_delta_tol) {
            printf("FAIL delta_seq out1[%d]: got %.9f, expected %.9f\n", vv, out[8 + vv], g_out1_expected[vv]);
            ++g_fails;
        }
    for (int i = 0; i < KD * VD; ++i)
        if (std::fabs(S[i] - g_S2_expected[i]) > g_delta_tol) {
            printf("FAIL delta_seq S2[%d]: got %.9f, expected %.9f\n", i, S[i], g_S2_expected[i]);
            ++g_fails;
        }

    // (b) 1 token, 2 heads: q/k/v [KD,2,1], g/beta [2,1]. head1 = copy of head0.
    float qh[16], kh[16], vh[16];
    float gh[2] = { g_g0, g_g0 };
    float bh[2] = { g_beta0, g_beta0 };
    std::memcpy(qh,     g_q0_in, 8 * sizeof(float)); std::memcpy(qh + 8,     g_q0_in, 8 * sizeof(float));
    std::memcpy(kh,     g_k0_in, 8 * sizeof(float)); std::memcpy(kh + 8,     g_k0_in, 8 * sizeof(float));
    std::memcpy(vh,     g_v0_in, 8 * sizeof(float)); std::memcpy(vh + 8,     g_v0_in, 8 * sizeof(float));
    float S2[128];
    std::memcpy(S2,       g_S0_in, 64 * sizeof(float));
    std::memcpy(S2 + 64,  g_S0_in, 64 * sizeof(float));
    float outh[16];
    nnml_ssm_delta_rule_update_seq(qh, KD * 2 * sizeof(float), kh, KD * 2 * sizeof(float),
                                   vh, VD * 2 * sizeof(float), gh, 2 * sizeof(float),
                                   bh, 2 * sizeof(float), S2, KD, VD, 2, 1,
                                   outh, VD * 2 * sizeof(float), 0, 1);
    for (int h = 0; h < 2; ++h)
        for (int vv = 0; vv < VD; ++vv)
            if (std::fabs(outh[h * 8 + vv] - g_out0_expected[vv]) > g_delta_tol) {
                printf("FAIL delta_seq head%d out0[%d]: got %.9f, expected %.9f\n", h, vv, outh[h * 8 + vv], g_out0_expected[vv]);
                ++g_fails;
            }
}

int main(void) {
    check_main_update();
    check_two_steps();
    check_conv_seq();
    check_null_and_degenerate();
    check_delta_rule_one_token();
    check_delta_rule_two_token();
    check_delta_seq();
    check_delta_rule_null_and_degenerate();
    check_rms_norm_gated();
    check_rms_norm_gated_inplace();
    check_rms_norm_gated_null_and_degenerate();
    check_partial_rotary();
    check_partial_rotary_inplace();
    check_partial_rotary_zero_pos();
    check_partial_rotary_zero_rotary();
    check_partial_rotary_null_and_degenerate();
    check_graph_ops();

    if (g_fails == 0) {
        printf("test-ssm: PASS (conv1d_update + delta_rule + rms_norm_gated + "
               "partial_rotary == numpy/HF reference; ssm graph ops mutate state "
               "across 2 tokens, match standalone)\n");
        return 0;
    }
    printf("test-ssm: FAIL (%d assertions)\n", g_fails);
    return 1;
}
